/* Inventory: pure-veg item master, batch/expiry tracking (FEFO), purchases → accounts, consumption, returns → debit notes, best price, recipe costing */
(()=>{
const J=window.J,{S,esc,inr,qf,r2,r3,money,money0,fmtDate,today,addDays,daysBetween,uid,periodRange,periodSeg,fld,txt,num,dateI,selO,area,toast}=J;
const GRPS=[["","Inventory"],["personal","Personal"],["expense","Expense"],["asset","Asset"]];
const ECATS=["Lighting & electricals","Kitchenware & utensils","Cleaning & housekeeping","Decor & furnishing","Packaging & disposables","Stationery & printing","Pooja & festival","Repairs & maintenance","Small appliances","Uniforms & linen","Garden & plants","Other"];
const PCATS=["Groceries & food","Clothing & footwear","Electronics & gadgets","Health & personal care","Household","Kids & school","Gifts & toys","Travel & accessories","Other"];
const ACATL=["Kitchen equipment","Refrigeration & cold storage","Furniture & fixtures","POS terminals & computers","Electrical installations","Vehicles","Air conditioning","Interiors & leasehold","Office equipment"];
const catsUsed=g=>{const k=g==="expense"?"ecat":"pcat";const set=new Set(g==="expense"?ECATS:PCATS);for(const m of J.all("moves"))if(m.type==="purchase")for(const l of m.lines||[])if(l[k])set.add(l[k]);return [...set]};
const catOf=l=>{const g=l.grp||(l.personal?"personal":"");return g==="expense"?l.ecat||"":g==="personal"?l.pcat||"":g==="asset"?l.acat||"":""};
const catCell=(i,g,v)=>g==="asset"?`<select name="ln-gcat-${i}" id="f-ln-gcat-${i}">${ACATL.map(c=>`<option ${v===c?"selected":""}>${c}</option>`).join("")}</select>`:g==="expense"||g==="personal"?`<input name="ln-gcat-${i}" id="f-ln-gcat-${i}" list="dl-${g}cat" value="${esc(v||"")}" placeholder="Choose or type">`:`<input name="ln-gcat-${i}" id="f-ln-gcat-${i}" value="" disabled placeholder="—">`;
J.act("lnGrp",el=>{const i=el.dataset.x;const td=document.getElementById("f-ln-gcat-"+i)?.parentElement;if(td)td.innerHTML=catCell(i,el.value,"")});
const UNITS=["KG","GM","LTR","ML","PCS","BUNDLE","PKT","BOX"];
const CONV={KG:{GM:0.001,KG:1},GM:{KG:1000,GM:1},LTR:{ML:0.001,LTR:1},ML:{LTR:1000,ML:1}};
const conv=(qty,from,to)=>{if(!from||from===to)return qty;const f=CONV[to]?.[from];return f?qty*f:qty};
const DEPTS=["Main Kitchen","Bakery","Sweet Section","Banquet","Tandoor","Beverages","Staff Meals","Counter Sell"];
const CATS=["Vegetables","Fruits","Dairy","Grains & Pulses","Flour & Atta","Spices & Masala","Oils & Ghee","Dry Fruits","Sweeteners","Bakery Inputs","Beverages","Packaging","Cleaning","Gas & Fuel","Other"];
const NONVEG=/\b(egg|eggs|chicken|mutton|lamb|goat|fish|prawns?|shrimps?|meat|beef|pork|gelatine?|lard|anchov(y|ies)|crab|lobster|squid|bacon|ham|sausage|salami|keema|tuna|salmon)\b/i;
const NOT_JAIN=/\b(onion|garlic|potato|aloo|carrot|beetroot|radish|mooli|ginger|adrak|lehsun|pyaz|yam|sweet potato|turnip)\b/i;
J.INV={UNITS,DEPTS,conv,CATS};

// ---------- derived stock (FEFO batches) ----------
J.onDerive(D=>{const items={};for(const it of J.all("items"))items[it.id]={qty:0,value:0,avg:0,batches:[],buys:[],used30:0,short:0,inInv:false,inOther:false};
  const moves=J.all("moves").sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:(a.createdAt||0)-(b.createdAt||0));const issue=new Map();const t30=addDays(today(),-30);
  const take=(I,q,batch)=>{let cost=0,left=q;let qs=I.batches.filter(b=>b.qty>0.0000001);if(batch){const b=qs.find(x=>x.batch===batch);if(b){const u=Math.min(b.qty,left);b.qty-=u;cost+=u*b.rate;left-=u}}
    qs=I.batches.filter(b=>b.qty>0.0000001).sort((a,b)=>(a.exp||"9999")<(b.exp||"9999")?-1:(a.exp||"9999")>(b.exp||"9999")?1:a.date<b.date?-1:1);
    for(const b of qs){if(left<=0.0000001)break;const u=Math.min(b.qty,left);b.qty-=u;cost+=u*b.rate;left-=u}if(left>0.0000001){I.short+=left;cost+=left*(I.avg||0)}return cost};
  for(const mv of moves){const costs=[];(mv.lines||[]).forEach((l,i)=>{const I=items[l.item];if(!I){costs.push(0);return}const q=+l.qty||0,rate=+l.rate||0;
      if(mv.type==="purchase"||(mv.type==="adjust"&&q>0)){I.avg=(I.qty>0?(I.qty*I.avg+q*rate)/(I.qty+q):rate)||I.avg;I.qty+=q;I.batches.push({batch:l.batch||mv.id+"-"+i,qty:q,orig:q,rate,exp:l.exp||"",mrp:l.mrp||0,mfg:l.mfg||"",expRaw:l.expRaw||"",date:mv.date,vendor:mv.vendor,move:mv.id});if(mv.type==="purchase"){if(l.grp||l.personal)I.inOther=true;else I.inInv=true}else I.inInv=true;if(mv.type==="purchase")I.buys.push({date:mv.date,vendor:mv.vendor,rate,qty:q});costs.push(q*rate)}
      else{const qq=Math.abs(q);const c=take(I,qq,mv.type==="return"||mv.auto?l.batch:null);I.qty-=qq;costs.push(c);if(mv.type==="consume"&&!mv.auto&&mv.date>=t30)I.used30+=qq}});issue.set(mv.id,costs)}
  let total=0,totalAvg=0;for(const [id,I] of Object.entries(items)){I.batches=I.batches.filter(b=>b.qty>0.0000001);I.value=I.batches.reduce((s,b)=>s+b.qty*b.rate,0);I.valueAvg=Math.max(0,I.qty)*I.avg;I.last=I.buys.at(-1)?.rate||I.avg||0;
    I.nextExp=I.batches.filter(b=>b.exp).map(b=>b.exp).sort()[0]||"";I.off=I.inOther&&!I.inInv&&Math.abs(I.qty)<0.0000001;total+=I.value;totalAvg+=I.valueAvg}
  D.inv={items,issue,total,totalAvg}});
const expState=exp=>{if(!exp)return null;const d=daysBetween(today(),exp);if(d<0)return ["bad","Expired",d];if(d<=3)return ["crit","Critical · "+d+"d",d];if(d<=7)return ["warn","Warning · "+d+"d",d];return ["ok","Fresh · "+d+"d",d]};
J.expState=expState;
const itemName=id=>J.get("items",id)?.name||"(deleted item)";
const unitOf=id=>J.get("items",id)?.unit||"";
const ui=()=>J.ui("inv",{val:"fifo",cat:"",q:"",period:"month",exp:"all",bpCat:"",pq:"",pg:"all",pc:""});
J.itemCost=(itemId,qty,unit)=>{const it=J.get("items",itemId);const I=J.D.inv?.items[itemId];if(!it||!I)return 0;return conv(+qty||0,unit||it.unit,it.unit)*(I.last||I.avg||0)};

// ---------- Stock in hand ----------
function vStock(){const U=ui(),inv=J.D.inv;const offN=J.all("items").filter(it=>inv.items[it.id]?.off).length;const items=J.all("items").filter(it=>(U.showOff||!inv.items[it.id]?.off)&&(!U.cat||it.cat===U.cat)&&(!U.q||(it.name+" "+(it.sub||"")).toLowerCase().includes(U.q.toLowerCase()))).sort((a,b)=>(a.cat||"").localeCompare(b.cat||"")||(a.sub||"").localeCompare(b.sub||"")||a.name.localeCompare(b.name));
  const all=J.all("items").filter(it=>!inv.items[it.id]?.off);const low=all.filter(it=>it.reorder&&inv.items[it.id]?.qty<=+it.reorder),batches=all.flatMap(it=>(inv.items[it.id]?.batches||[]).map(b=>({...b,it})));
  const expd=batches.filter(b=>expState(b.exp)?.[0]==="bad"),soon=batches.filter(b=>["crit","warn"].includes(expState(b.exp)?.[0]));
  const val=U.val==="avg"?"valueAvg":"value";const stockBal=J.sysAcc("stock")?J.balanceOf(J.sysAcc("stock").id):0;const totalVal=U.val==="avg"?inv.totalAvg:inv.total;
  const groups={};for(const it of items){const g=(it.cat||"Other")+(it.sub?" · "+it.sub:"");(groups[g]??=[]).push(it)}
  return `<div class="kpis">${J.kpi("Stock value ("+(U.val==="avg"?"weighted avg":"FIFO")+")",money(totalVal),all.length+" items")}${J.kpi("Below reorder level",String(low.length),low.slice(0,3).map(x=>x.name).join(", ")||"all stocked")}${J.kpi("Expiring in 7 days",String(soon.length),"batches","inventory/expiry")}${J.kpi("Expired, still in stock",String(expd.length),expd.length?"remove or return":"none","inventory/expiry")}${J.kpi("Stock in books",money(stockBal),Math.abs(stockBal-totalVal)>1?"post month-end to update":"in step")}</div>
  <div class="filters"><div class="seg">${[["fifo","FIFO"],["avg","Weighted avg"]].map(([k,l])=>`<button data-set="inv.val=${k}" aria-pressed="${U.val===k}">${l}</button>`).join("")}</div>
    ${fld("Category",`<select id="iv-cat" data-ui="inv.cat"><option value="">All</option>${CATS.map(c=>`<option ${U.cat===c?"selected":""}>${c}</option>`).join("")}</select>`)}${fld("Search",`<input id="iv-q" data-ui="inv.q" value="${esc(U.q)}" placeholder="Item or subcategory">`)}
    ${offN?`<button class="btn w" data-set="inv.showOff=${U.showOff?"":"1"}" aria-pressed="${!!U.showOff}" title="Items bought only as Personal / Expense / Asset are kept out of stock">${U.showOff?"Hide":"Show"} ${offN} personal / expense items</button>`:""}<div class="row" style="margin-left:auto"><button class="btn w" data-a="adjStock">Stock count / adjust</button><button class="btn w" data-a="postStock">Post month-end stock to accounts</button><button class="btn" data-a="exportStock">Export CSV</button></div></div>
  <div class="panel"><div class="tbl-wrap"><table><thead><tr><th>Item</th><th class="num">In hand</th><th class="num">Reorder at</th><th class="num">Used 30d</th><th class="num">Last rate</th><th class="num">Value</th><th>Nearest expiry</th><th></th></tr></thead><tbody>
  ${items.length?Object.entries(groups).map(([g,its])=>`<tr><td colspan="8" style="font-weight:700;color:var(--bahi);font-size:11.5px;letter-spacing:.06em;text-transform:uppercase">${esc(g)}</td></tr>`+its.map(it=>{const I=inv.items[it.id];const lowF=it.reorder&&I.qty<=+it.reorder;const es=expState(I.nextExp);
    return `<tr><td><div class="row" style="gap:8px;flex-wrap:nowrap">${it.img?`<span class="avatar" style="width:28px;height:28px"><img src="${esc(it.img)}" alt=""></span>`:""}<span>${esc(it.name)}${I.off?' <span class="chip">Personal / expense only</span>':""}</span></div></td><td class="num">${I.qty<0?`<span class="chip bad">${qf.format(I.qty)}</span>`:qf.format(I.qty)} ${esc(it.unit)}</td><td class="num">${it.reorder?qf.format(it.reorder):"—"} ${lowF?'<span class="chip warn">Low</span>':""}</td><td class="num muted">${qf.format(I.used30)}</td><td class="num">${I.last?inr.format(I.last):"—"}</td><td class="num">${inr.format(I[val])}</td><td>${es?`<span class="chip ${es[0]}">${fmtDate(I.nextExp)}</span>`:'<span class="muted">—</span>'}</td><td style="white-space:nowrap"><button class="btn small w" data-a="useItem" data-x="${it.id}" title="Log consumption">Use</button> <button class="btn small w" data-a="buyItem" data-x="${it.id}" title="New purchase">Buy</button> <button class="btn small w" data-a="itemBills" data-x="${it.id}" title="Purchase bills with this item — open one to edit or change its group">Bills</button> <button class="btn small w" data-a="itemUses" data-x="${it.id}" title="Consumption entries for this item">Uses</button></td></tr>`}).join("")).join(""):J.emptyRow(8,"No items yet","Add items to the item master, or import a CSV of items.")}
  </tbody></table></div></div>`}
function vExpiry(){const U=ui(),inv=J.D.inv;const t=today();const rows=J.all("items").flatMap(it=>(inv.items[it.id]?.batches||[]).map(b=>({...b,it,st:expState(b.exp)}))).filter(b=>U.exp==="all"?true:U.exp==="none"?!b.exp:b.st?.[0]===U.exp).sort((a,b)=>(a.exp||"9999").localeCompare(b.exp||"9999"));
  const cnt=k=>J.all("items").flatMap(it=>inv.items[it.id]?.batches||[]).filter(b=>expState(b.exp)?.[0]===k).length;
  return `<div class="filters"><div class="seg">${[["all","All batches"],["bad","Expired ("+cnt("bad")+")"],["crit","≤ 3 days ("+cnt("crit")+")"],["warn","≤ 7 days ("+cnt("warn")+")"],["ok","Fresh"],["none","No expiry"]].map(([k,l])=>`<button data-set="inv.exp=${k}" aria-pressed="${U.exp===k}">${l}</button>`).join("")}</div></div>
  <div class="panel"><div class="tbl-wrap"><table><thead><tr><th>Status</th><th>Item</th><th>Batch</th><th>Received</th><th>Vendor</th><th class="num">Remaining</th><th class="num">Value at risk</th><th>Expires</th><th></th></tr></thead><tbody>
  ${rows.length?rows.map(b=>`<tr><td>${b.st?`<span class="chip ${b.st[0]}">${esc(b.st[1])}</span>`:'<span class="chip plain">No date</span>'}</td><td>${esc(b.it.name)}</td><td class="mono">${esc(b.batch)}${b.mfg||b.expRaw||b.mrp?`<div class="muted" style="font-family:inherit;font-size:11px">${b.mfg?"Mfg "+fmtDate(b.mfg)+" · ":""}${b.expRaw?"Pack: "+esc(b.expRaw):""}${b.mrp?" · MRP ₹"+b.mrp:""}</div>`:""}</td><td>${fmtDate(b.date)}</td><td>${esc(J.accName(b.vendor)||"")}</td><td class="num">${qf.format(b.qty)} ${esc(b.it.unit)}</td><td class="num">${inr.format(b.qty*b.rate)}</td><td>${fmtDate(b.exp)}</td><td style="white-space:nowrap"><button class="btn small w" data-a="useBatch" data-x="${b.it.id}|${esc(b.batch)}">Write off</button>${b.vendor?` <button class="btn small w" data-a="retBatch" data-x="${b.it.id}|${esc(b.batch)}">Return</button>`:""}</td></tr>`).join(""):J.emptyRow(9,"Nothing in this view","Batches are created automatically from each purchase line.")}
  </tbody></table></div></div><p class="hint">Stock is issued first-expiry-first-out, so the batch closest to expiry is used first. Fresh means more than 7 days left.</p>`}

// ---------- Purchases ----------
function moveTable(type){const U=ui(),[from,to]=periodRange(U.period,U);const inv=J.D.inv;
  const P=type==="purchase",SK="q"+type,q=(U[SK]||"").trim().toLowerCase(),MK=S.route.mod==="mkjinv",pg=P?(MK?"personal":(U.pg==="personal"?"all":U.pg||"all")):"all",pc=P?U.pc||"":"";
  const lineHit=(m,l)=>{const g=l.grp||(l.personal?"personal":"")||"inv";if(P&&(g==="personal")!==MK)return false;if(pg!=="all"&&g!==pg)return false;if(pc&&catOf(l)!==pc)return false;if(q){const t=(itemName(l.item)+" "+(J.get("items",l.item)?.sub||"")+" "+catOf(l)).toLowerCase();const head=((m.inv||"")+" "+(m.vendor?J.accName(m.vendor):"")+" "+(m.dept||"")+" "+(m.note||"")+" "+(m.payNote||"")).toLowerCase();return t.includes(q)||head.includes(q)}return true};
  const filt=!!(q||pg!=="all"||pc||P);
  const rows=J.all("moves").filter(m=>m.type===type&&(q?true:m.date>=from&&m.date<=to)&&(!filt||(m.lines||[]).some(l=>lineHit(m,l)))).sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||0)-(a.createdAt||0));
  const lsum=m=>(m.lines||[]).filter(l=>!filt||lineHit(m,l)).reduce((x,l)=>x+(+l.qty||0)*(+l.rate||0)*(1+(+l.gst||0)/100),0);
  const catTot={};if(P&&(pg==="expense"||pg==="personal"||pg==="asset"))for(const m of rows)for(const l of m.lines||[])if(lineHit(m,l)){const c=catOf(l)||"Uncategorised";catTot[c]=(catTot[c]||0)+(+l.qty||0)*(+l.rate||0)*(1+(+l.gst||0)/100)}
  const tot=filt?rows.reduce((s,m)=>s+lsum(m),0):rows.reduce((s,m)=>s+(type==="purchase"||type==="return"?(m.lines||[]).reduce((x,l)=>x+(+l.qty||0)*(+l.rate||0)*(1+(+l.gst||0)/100),0):(inv.issue.get(m.id)||[]).reduce((x,c)=>x+c,0)),0);
  const btn={purchase:["newPurchase","New purchase"],consume:["newConsume","Log consumption"],return:["newReturn","New return / debit note"],adjust:["adjStock","Stock count / adjust"]}[type];
  const cats=P&&pg!=="all"&&pg!=="inv"?[...new Set(J.all("moves").filter(m=>m.type==="purchase").flatMap(m=>(m.lines||[]).filter(l=>(l.grp||(l.personal?"personal":""))===pg).map(catOf)).filter(Boolean))].sort():[];
  return `<div class="filters">${fld(P?"Search item, invoice or vendor":type==="consume"?"Search item, department or note":"Search item or note",`<input id="pu-q-${type}" data-ui="inv.${SK}" value="${esc(U[SK]||"")}" placeholder="Type part of an item name…" style="min-width:240px">`)}${P&&!MK?`<div class="seg" role="group" aria-label="Group">${[["all","All lines"],["inv","Inventory"],["expense","Expense"],["asset","Asset"]].map(([k,l])=>`<button data-set="inv.pg=${k}" aria-pressed="${pg===k}">${l}</button>`).join("")}</div>${cats.length?fld("Category",`<select id="pu-c" data-ui="inv.pc"><option value="">All categories</option>${cats.map(c=>`<option ${pc===c?"selected":""}>${esc(c)}</option>`).join("")}</select>`):""}`:""}${q?`<span class="hint">Searching all dates</span> <button class="btn small w" data-set="inv.${SK}=">Clear search</button>`:""}</div>
  ${Object.keys(catTot).length?`<div class="row" style="gap:6px;flex-wrap:wrap;margin:0 0 10px">${Object.entries(catTot).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<button class="chip ${pc===c?"ok":""}" data-set="inv.pc=${c==="Uncategorised"?"":esc(c)}" style="cursor:pointer">${esc(c)} · ${money(v)}</button>`).join("")}</div>`:""}
  <div class="filters">${periodSeg("inv",U.period,U)}<span class="muted" style="margin-left:auto">${rows.length} records · ${money(tot)}${filt?" (matching lines)":""}</span>${type==="purchase"?`<button class="btn" data-a="exportPurch">Export CSV</button>`:""}<button class="btn primary w" data-a="${btn[0]}">${btn[1]}</button></div>
  <div class="panel"><div class="tbl-wrap"><table><thead><tr><th>${type==="purchase"?"Ordered":"Date"}</th><th>${type==="consume"?"Department":type==="adjust"?"Reason":"Vendor"}</th><th>${type==="purchase"||type==="return"?"Invoice / note":"Items"}</th><th>Lines</th><th class="num">${type==="purchase"?"Bill total":type==="return"?"Debit note":"Cost"}</th><th>${type==="purchase"?"Payment":""}</th><th></th></tr></thead><tbody>
  ${rows.length?rows.map(m=>{const amt=type==="purchase"||type==="return"?(m.lines||[]).reduce((x,l)=>x+(+l.qty||0)*(+l.rate||0)*(1+(+l.gst||0)/100),0):(inv.issue.get(m.id)||[]).reduce((x,c)=>x+c,0);
    return `<tr><td style="white-space:nowrap">${fmtDate(m.date)}${type==="purchase"&&m.dlv?`<div class="hint">Delivered ${fmtDate(m.dlv)}</div>`:""}</td><td>${esc(type==="consume"?m.dept:type==="adjust"?(m.note||"Count"):J.accName(m.vendor))}</td><td>${type==="purchase"||type==="return"?`<span class="mono">${esc(m.inv||"—")}</span>`:esc((m.lines||[]).slice(0,3).map(l=>itemName(l.item)).join(", "))}</td><td class="muted">${(m.lines||[]).map(l=>{const h=filt&&lineHit(m,l);const t=esc(itemName(l.item))+" "+qf.format(l.qty)+" "+esc(unitOf(l.item))+(type==="purchase"&&(l.grp||l.personal)?` <span class="chip warn" style="font-size:10px">${esc(l.grp||"personal")}${catOf(l)?" · "+esc(catOf(l)):""}</span>`:"");return h?`<mark style="color:var(--ink,inherit)">${t}</mark>`:t}).join(" · ")}</td><td class="num">${money(filt?lsum(m):amt)}</td><td>${type==="purchase"?(m.paid?`<span class="chip ok">Paid · ${esc(J.accName(m.paid))}</span>`:(m.payNote?`<span class="chip warn" title="Paid on the site by ${esc(m.payNote)} — the debit will be matched to this bill when that bank or card statement is imported">${esc(m.payNote)} · match with bank</span>`:`<span class="chip warn">On credit${m.due?" · due "+fmtDate(m.due):""}</span>`)):""}</td><td style="white-space:nowrap">${type==="purchase"&&!(m.docs||[]).length&&!(J.get("vouchers",m.vid)?.docs||[]).length&&!m.auto?`<button type="button" class="chip warn" data-a="docsOpen" data-x="${"vouchers|"+m.vid}" data-t="${esc("Bill · "+(m.inv||""))}" title="No bill file saved with this entry — tap to upload">No bill · upload</button> `:""}${type==="purchase"&&m.vid?J.docsBtn("vouchers",{id:m.vid,docs:J.get("vouchers",m.vid)?.docs||[]},"Bill · "+(m.inv||"")):""}${(m.docs||[]).length||!(type==="purchase"&&m.vid)?J.docsBtn("moves",m,"Purchase "+(m.inv||"")):""} ${m.auto?`<span class="chip plain">${esc(m.dept)} · from purchase</span> <button class="btn small" data-a="editMove" data-x="${m.src}">Open purchase</button>`:`<button class="btn small" data-a="editMove" data-x="${m.id}">Open</button> ${J.confirmBtn("mv:"+m.id,"Delete this record","delMove",m.id)}`}</td></tr>`}).join(""):J.emptyRow(7,"No records in this period","Change the period, or add one.")}
  </tbody></table></div></div>`}
J.invViews={purch:()=>moveTable("purchase")};const vPurch=()=>moveTable("purchase"),vCons=()=>moveTable("consume"),vRet=()=>moveTable("return"),vAdj=()=>moveTable("adjust");

const itemOpts=sel=>`<option value="">— item —</option>`+CATS.map(c=>{const its=J.all("items").filter(i=>(i.cat||"Other")===c&&i.active!==false).sort((a,b)=>a.name.localeCompare(b.name));return its.length?`<optgroup label="${esc(c)}">${its.map(i=>`<option value="${i.id}" ${i.id===sel?"selected":""}>${esc(i.name)} (${esc(i.unit)})</option>`).join("")}</optgroup>`:""}).join("")+(J.qaOpts?J.qaOpts("item"):"");J.itemOpts=itemOpts;
function lineRow(type,i,l={}){const it=l.item?J.get("items",l.item):null;
  if(type==="purchase")return `<tr><td style="min-width:180px"><select name="ln-item-${i}" id="f-ln-item-${i}" data-ach="lnItem" data-x="${i}">${itemOpts(l.item)}</select></td><td style="min-width:80px"><input name="ln-qty-${i}" id="f-ln-qty-${i}" type="number" step="any" value="${esc(l.qty??"")}"></td><td style="min-width:90px"><input name="ln-rate-${i}" id="f-ln-rate-${i}" type="number" step="any" value="${esc(l.rate??"")}"></td><td style="min-width:70px"><select name="ln-gst-${i}" id="f-ln-gst-${i}">${["0","5","12","18","28"].map(r=>`<option ${String(l.gst??"0")===r?"selected":""}>${r}</option>`).join("")}</select></td><td style="min-width:80px"><input name="ln-mrp-${i}" id="f-ln-mrp-${i}" type="number" step="any" value="${esc(l.mrp??"")}" placeholder="per pack"></td><td style="min-width:110px"><input name="ln-mfg-${i}" id="f-ln-mfg-${i}" value="${esc(l.mfg?fmtPack(l.mfg):"")}" placeholder="dd/mm/yy or mm/yy" data-ach="lnExp" data-x="${i}"></td><td style="min-width:150px"><input name="ln-expraw-${i}" id="f-ln-expraw-${i}" value="${esc(l.expRaw||(l.exp?fmtPack(l.exp):""))}" placeholder="date · mm/yy · 6 months" data-ach="lnExp" data-x="${i}"><div class="hint" id="f-ln-expc-${i}" style="font-size:11px">${l.exp?"→ "+fmtDate(l.exp):""}</div></td><td style="min-width:110px"><select name="ln-grp-${i}" id="f-ln-grp-${i}" title="Where this line belongs" data-ach="lnGrp" data-x="${i}">${GRPS.map(([v,t])=>`<option value="${v}" ${(l.grp||(l.personal?"personal":""))===v?"selected":""}>${t}</option>`).join("")}</select></td><td style="min-width:170px">${catCell(i,l.grp||(l.personal?"personal":""),catOf(l))}</td></tr>`;
  if(type==="consume"||type==="adjust")return `<tr><td style="min-width:200px"><select name="ln-item-${i}" id="f-ln-item-${i}">${itemOpts(l.item)}</select></td><td style="min-width:90px"><input name="ln-qty-${i}" id="f-ln-qty-${i}" type="number" step="any" value="${esc(l.qty??"")}" placeholder="${type==="adjust"?"+/−":""}"></td>${type==="adjust"?`<td style="min-width:90px"><input name="ln-rate-${i}" id="f-ln-rate-${i}" type="number" step="any" value="${esc(l.rate??"")}" placeholder="for +"></td>`:""}</tr>`;
  return ""}
function readLines(fd,type){const out=[];for(let i=0;i<60;i++){if(!(("ln-item-"+i) in fd))break;const item=fd["ln-item-"+i],qty=+fd["ln-qty-"+i];if(!item||!qty)continue;const l={item,qty:r3(qty)};if(type==="purchase"){l.rate=+fd["ln-rate-"+i]||0;l.gst=+fd["ln-gst-"+i]||0;l.mrp=+fd["ln-mrp-"+i]||0;const mf=J.packDate(fd["ln-mfg-"+i]);l.mfg=mf||"";l.expRaw=(fd["ln-expraw-"+i]||"").trim();l.exp=J.expiryCalc(l.expRaw,l.mfg,fd.date||today()).exp||"";const gp=fd["ln-grp-"+i]||"";if(gp){l.grp=gp;if(gp==="personal")l.personal=true}const ol=fd.__old?.[i];if(ol)for(const k of ["ref","url","seller","model","wty","wtyu","acat","ecat","pcat","ext"])if(ol[k]!=null&&ol.item===item)l[k]=ol[k];const gc=(fd["ln-gcat-"+i]||"").trim();if(gp==="expense")l.ecat=gc;else if(gp==="personal")l.pcat=gc;else if(gp==="asset"&&gc)l.acat=gc}if(type==="adjust")l.rate=+fd["ln-rate-"+i]||0;out.push(l)}return out}
J.act("itemBills",el=>{const n=J.get("items",el.dataset.x)?.name||"";J.setUI("inv.qpurchase",n);J.setUI("inv.pg","all");J.setUI("inv.pc","");J.go("inventory","purchases")});
J.act("itemUses",el=>{const n=J.get("items",el.dataset.x)?.name||"";J.setUI("inv.qconsume",n);J.go("inventory","consumption")});
J.act("lnItem",el=>{const it=J.get("items",el.value);const I=J.D.inv?.items[el.value];const i=el.dataset.x;const rate=document.getElementById("f-ln-rate-"+i);if(rate&&!rate.value&&I?.last)rate.value=r2(I.last);const g=document.getElementById("f-ln-gst-"+i);if(g&&it?.gst!=null)g.value=String(it.gst);const e=document.getElementById("f-ln-expraw-"+i);if(e&&!e.value&&it?.shelf){e.value=it.shelf+" days";J.run("lnExp",e)}const mr=document.getElementById("f-ln-mrp-"+i);if(mr&&!mr.value&&it?.mrp)mr.value=it.mrp});
const fmtPack=d=>{const [y,m,dd]=String(d).split("-");return dd+"/"+m+"/"+y};
J.act("lnExp",el=>{const i=el.dataset.x;const raw=document.getElementById("f-ln-expraw-"+i)?.value,mfg=document.getElementById("f-ln-mfg-"+i)?.value;const r=J.expiryCalc(raw,mfg,document.getElementById("f-date")?.value||today());const o=document.getElementById("f-ln-expc-"+i);if(o)o.innerHTML=r.exp?`→ <b>${fmtDate(r.exp)}</b> <span class="muted">(${esc(r.how)})</span>`:raw?`<span style="color:var(--bad,#b91c1c)">${esc(r.how)}</span>`:""});
J.act("addLines",el=>{const tb=document.getElementById("lnBody");const type=el.dataset.x;const n=tb.querySelectorAll("tr").length;tb.insertAdjacentHTML("beforeend",[0,1,2,3].map(k=>lineRow(type,n+k)).join(""))});

const PLATS=["Direct from supplier","Flipkart","Flipkart Minutes","Amazon","Instamart","Zepto","Blinkit","BigBasket","Zomato Hyperpure","Other online"];
async function savePurchase(fd,old){fd.__old=old?.lines;const lines=readLines(fd,"purchase");const billFiles=[...(document.getElementById("pur-bill")?.files||[]),...(document.getElementById("pur-cam")?.files||[])];const hadDocs=(old?.vid&&(J.get("vouchers",old.vid)?.docs||[]).length)||(old?.docs||[]).length;
  const plat=fd.plat&&fd.plat!==PLATS[0]?fd.plat:"";if(!fd.vendor&&plat&&plat!=="Other online"){const nm=plat==="Instamart"?"Swiggy Instamart":plat;fd.vendor=J.all("accounts").find(a=>a.kind==="vendor"&&a.name.toLowerCase()===nm.toLowerCase())?.id||await J.ensureAcc(nm,"vendor")}
  if(!fd.vendor)return "Choose the vendor (or the platform you ordered from).";if(!billFiles.length&&!hadDocs&&!fd.noBill)return "Upload the bill (photo, PDF or Excel) — it is saved with the entry in Accounts. If there really is no bill, tick “No bill file available”.";if(!lines.length)return "Add at least one line with item and quantity.";if(lines.some(l=>!(l.rate>0)))return "Every line needs a rate.";
  const id=old?.id||uid(),stamp=fd.date.replace(/-/g,"");lines.forEach((l,i)=>l.batch=old?.lines?.[i]?.item===l.item&&old.lines[i].batch?old.lines[i].batch:"BATCH-"+stamp+"-"+id.slice(-4).toUpperCase()+(i+1));
  const taxable=r2(lines.reduce((s,l)=>s+l.qty*l.rate,0)),gstByRate={};let tax=0;for(const l of lines){const t=r2(l.qty*l.rate*l.gst/100);tax+=t;if(l.gst){gstByRate[l.gst]=gstByRate[l.gst]||[0,0];gstByRate[l.gst][0]+=r2(l.qty*l.rate);gstByRate[l.gst][1]+=t}}tax=r2(tax);const total=r2(taxable+tax);
  const head=J.sysAcc("purch")?.id||await J.ensureAcc("Kitchen Purchases (Raw Material)","expense","purch");const reg=!!J.settings().gstin;/* not GST-registered: the GST paid stays inside the expense (and is listed in Accounts → GST paid) */const igst=tax&&reg?(J.sysAcc("igst")?.id||await J.ensureAcc("Input GST","tax","igst")):null;
  const L=[{a:head,dr:reg?taxable:total,cr:0},...(igst?[{a:igst,dr:tax,cr:0}]:[]),{a:fd.vendor,dr:0,cr:total}];if(fd.paid)L.push({a:fd.vendor,dr:total,cr:0},{a:fd.paid,dr:0,cr:total});
  const v=await J.postVoucher({id:old?.vid,type:"purchase",date:fd.date,lines:L,party:fd.vendor,ref:fd.inv,narr:"Stock purchase · "+lines.map(l=>itemName(l.item)).slice(0,4).join(", ")+(lines.length>4?"…":""),gst:Object.keys(gstByRate).length?{in:gstByRate}:null,src:{col:"moves",id,label:"Inventory"},f:{due:fd.due,...(plat?{plat}:{})}});
  if(billFiles.length){const n=await J.attachFiles("vouchers",v.id,billFiles,"Bill / invoice"+(plat?" · "+plat:"")+(fd.inv?" · "+fd.inv:""));if(n)toast(n+" bill file"+(n>1?"s":"")+" saved with "+v.no)}
  const doc={...(old||{}),id,type:"purchase",dlv:fd.dlv||"",payNote:(fd.payNote||"").trim(),date:fd.date,m:fd.date.slice(0,7),vendor:fd.vendor,inv:fd.inv,due:fd.due||"",paid:fd.paid||"",lines,note:fd.note||"",vid:v.id,plat,noBill:!!fd.noBill&&!billFiles.length&&!hadDocs,createdAt:old?.createdAt||Date.now()};await J.store.put("moves",doc);await J.syncGroups(id,doc);toast((old?"Updated ":"Saved ")+"purchase · "+v.no+" posted to accounts")}
function purchaseDrawer(old,preItem){const n=Math.max(5,(old?.lines?.length||0)+1);const lines=old?.lines||(preItem?[{item:preItem,rate:J.D.inv.items[preItem]?.last?r2(J.D.inv.items[preItem].last):"",gst:J.get("items",preItem)?.gst??0}]:[]);
  J.drawer({docs:old?.vid?["vouchers",old.vid]:["moves",old?.id],title:old?"Purchase "+(old.inv||""):"New purchase",wide:true,submit:old?"Save purchase":"Save & post to accounts",body:`<div class="form">${fld("Order / invoice date",dateI("date",old?.date||today()))}${fld("Delivered on",dateI("dlv",old?.dlv))}${fld("Ordered from",`<select name="plat" id="f-plat">${PLATS.map(x=>`<option ${x===(old?.plat||PLATS[0])?"selected":""}>${esc(x)}</option>`).join("")}</select>`)}${fld("Vendor",J.selA("vendor",["vendor"],old?.vendor,"Choose vendor… (or pick the platform)"))}${fld("Invoice no.",txt("inv",old?.inv))}${fld("Due date",dateI("due",old?.due))}${fld("Paid now from",J.selA("paid",J.MONEY,old?.paid,"Not paid — on credit"))}${fld("Payment mode (as per order)",txt("payNote",old?.payNote,"e.g. BHIM UPI, GPay, Visa 5598"))}</div>
    <div class="tbl-wrap"><table class="lines-tbl"><thead><tr><th>Item</th><th>Qty</th><th>Rate (₹/unit)</th><th>GST %</th><th>MRP ₹</th><th>Mfg date</th><th>Expiry as on pack</th><th title="Inventory stays in stock; Personal, Expense and Asset lines are taken out of stock automatically">Group</th><th title="Expense / personal / asset category">Category</th></tr></thead><tbody id="lnBody">${[...Array(n)].map((_,i)=>lineRow("purchase",i,lines[i])).join("")}</tbody></table></div><p class="hint" style="margin:2px 0 0">Expiry: type it exactly as printed — a full date (15/03/27), month and year only (03/27 → end of that month), or "Best before 6 months" / "9 months" / "180 days" (counted from the mfg date). The app works out the date. <b>Group</b> sets where each line belongs and can be changed any time: <b>Inventory</b> stays in stock; <b>Personal</b> moves the cost to Owner's personal purchases; <b>Expense</b> to Consumables & small items; <b>Asset</b> adds it to the fixed-asset register. <b>Category</b>: for Expense lines pick or type a category (Lighting, Kitchenware…) — each category gets its own expense ledger; for Asset lines it sets the depreciation class. Non-inventory lines are taken out of stock automatically.</p>
    <datalist id="dl-expensecat">${catsUsed("expense").map(c=>`<option value="${esc(c)}">`).join("")}</datalist><datalist id="dl-personalcat">${catsUsed("personal").map(c=>`<option value="${esc(c)}">`).join("")}</datalist><button type="button" class="btn small" data-a="addLines" data-x="purchase">Add rows</button>${fld("Note",txt("note",old?.note))}
    <div class="panel pb" style="margin-top:10px"><h3 class="ph" style="padding:0">Bill / invoice</h3><p class="hint" style="margin:0">Upload the bill — the supplier's invoice, or the Flipkart, Amazon, Instamart, Zepto or Blinkit order invoice (PDF, screenshot, photo or Excel). It is saved with this entry in Accounts.</p>
      <div class="row" style="gap:8px;flex-wrap:wrap;align-items:flex-end">${J.attachInput("pur-bill","Choose bill file(s)")}<label class="f">…or take a photo<input type="file" id="pur-cam" accept="image/*" capture="environment"></label></div>
      <label class="row" style="gap:6px;margin-top:6px"><input type="checkbox" name="noBill" ${old?.noBill?"checked":""}> No bill file available</label>${old?.vid&&(J.get("vouchers",old.vid)?.docs||[]).length?`<p class="hint" style="margin:4px 0 0">${(J.get("vouchers",old.vid).docs||[]).length} bill file(s) already saved — shown below.</p>`:""}</div>
    <p class="hint">Each line becomes a batch numbered from the invoice date (BATCH-YYYYMMDD-…). Saving posts the bill to the vendor's ledger, Kitchen Purchases and Input GST${old?.vid?" and updates "+esc(J.get("vouchers",old.vid)?.no||""):""}.</p>
    ${J.all("items").length?"":`<div class="note">Add items to the item master first.</div>`}`,onSubmit:fd=>savePurchase(fd,old)})}

// bill from an online platform (Flipkart, Amazon, Instamart, Zepto, Blinkit…): pick the file, the platform / invoice no. / date are read when possible, and the purchase form opens with the bill already attached
const PLAT_RE=[["Flipkart Minutes",/flipkart\s*minutes/i],["Flipkart",/flipkart|ekart/i],["Amazon",/amazon|amzn/i],["Instamart",/instamart|swiggy/i],["Zepto",/zepto|kiranakart/i],["Blinkit",/blinkit|grofers/i],["BigBasket",/big\s*basket|innovative retail/i],["Zomato Hyperpure",/hyperpure/i]];
J.act("platBill",()=>{const i=document.createElement("input");i.type="file";i.multiple=true;i.accept="image/*,application/pdf,.xls,.xlsx,.xlsm,.ods,.csv";
  i.onchange=async()=>{const files=[...i.files];if(!files.length)return;
    // Flipkart / Flipkart Minutes tax-invoice PDFs are read in full (items, GST, Flipkart vs Flipkart Minutes) and go to the bill review
    try{const pf=files.filter(x=>/pdf/i.test(x.type)||/\.pdf$/i.test(x.name));if(pf.length===files.length&&J.billParseFile){const ps=await Promise.all(pf.map(f=>J.billParseFile(f).catch(()=>null)));if(ps.every(b=>b&&b.vendorKey==="flipkart")){await J.billStage(pf);return}}}catch(e){console.warn("flipkart parse",e)}
    let txt=files.map(f=>f.name).join(" ");
    try{const f=files.find(x=>/pdf/i.test(x.type));if(f){const lib=await J.loadPdfJs();const pdf=await lib.getDocument({data:new Uint8Array(await f.arrayBuffer()),isEvalSupported:false}).promise;const pg=await pdf.getPage(1);txt+=" "+(await pg.getTextContent()).items.map(x=>x.str).join(" ")}}catch(e){console.warn("bill text",e)}
    const plat=(PLAT_RE.find(([,re])=>re.test(txt))||[])[0]||"";const inv=((txt.match(/(?:invoice|order)\s*(?:no\.?|number|#|id)\s*[:#]?\s*([A-Z0-9][A-Z0-9\-\/]{5,})/i)||[])[1]||"");
    const dm=txt.match(/\b(\d{1,2})[-\/.](\d{1,2})[-\/.](20\d{2})\b/);const date=dm?dm[3]+"-"+dm[2].padStart(2,"0")+"-"+dm[1].padStart(2,"0"):"";
    purchaseDrawer(null);setTimeout(()=>{const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));const inp=document.getElementById("pur-bill");if(inp)inp.files=dt.files;
      const set=(id,v)=>{const e=document.getElementById(id);if(e&&v)e.value=v};set("f-plat",plat);set("f-inv",inv);if(date&&date<=today())set("f-date",date);
      toast(files.length+" bill file"+(files.length>1?"s":"")+" attached"+(plat?" · "+plat:"")+" — add the items and save")},150)};i.click()});
async function saveSimple(type,fd,old){const lines=readLines(fd,type);if(!lines.length)return "Add at least one line with item and quantity.";if(type==="adjust"&&lines.some(l=>l.qty>0&&!(l.rate>0)))return "Lines that add stock need a rate.";
  const id=old?.id||uid();await J.store.put("moves",{id,type,date:fd.date,m:fd.date.slice(0,7),dept:fd.dept||"",note:fd.note||"",lines,createdAt:old?.createdAt||Date.now()});toast(type==="consume"?"Consumption logged":"Stock adjusted")}
function consumeDrawer(old,pre){const n=Math.max(6,(old?.lines?.length||0)+1);const lines=old?.lines||(pre?[pre]:[]);
  J.drawer({docs:["moves",old?.id],title:old?"Consumption":"Log consumption",wide:true,submit:"Save",body:`<div class="form">${fld("Date",dateI("date",old?.date||today()))}${fld("Department",selO("dept",DEPTS,old?.dept||"Main Kitchen").replace("<select ",'<select data-ach="deptPick" '))}${fld("Reason",selO("note",["Kitchen usage","Direct Sell","Wastage / spoilage","Expired write-off","Staff meals","Sampling"],old?.note||(old?.dept==="Counter Sell"?"Direct Sell":"Kitchen usage")))}</div>
    <div class="tbl-wrap"><table class="lines-tbl"><thead><tr><th>Item</th><th>Qty used</th></tr></thead><tbody id="lnBody">${[...Array(n)].map((_,i)=>lineRow("consume",i,lines[i])).join("")}</tbody></table></div><button type="button" class="btn small" data-a="addLines" data-x="consume">Add rows</button>
    <p class="hint">Stock is drawn from the batch nearest expiry first, and costed at that batch's purchase rate.</p>`,onSubmit:fd=>saveSimple("consume",fd,old)})}
function adjustDrawer(old){const n=Math.max(6,(old?.lines?.length||0)+1);
  J.drawer({docs:["moves",old?.id],title:"Stock count / adjustment",wide:true,submit:"Save adjustment",body:`<div class="form">${fld("Date",dateI("date",old?.date||today()))}${fld("Reason",txt("note",old?.note||"Physical count","Physical count, opening stock…"))}</div>
    <div class="tbl-wrap"><table class="lines-tbl"><thead><tr><th>Item</th><th>Qty (+ add / − remove)</th><th>Rate for additions</th></tr></thead><tbody id="lnBody">${[...Array(n)].map((_,i)=>lineRow("adjust",i,old?.lines?.[i])).join("")}</tbody></table></div><button type="button" class="btn small" data-a="addLines" data-x="adjust">Add rows</button>
    <p class="hint">Use this for opening stock and to correct the system after a physical count. Current quantities are on the Stock tab.</p>`,onSubmit:fd=>saveSimple("adjust",fd,old)})}
function returnDrawer(old,pre){const inv=J.D.inv;const vendor=old?.vendor||pre?.vendor||"";
  const opts=J.all("items").flatMap(it=>(inv.items[it.id]?.batches||[]).filter(b=>b.vendor&&(!vendor||b.vendor===vendor)).map(b=>({it,b})));
  const l0=old?.lines?.[0]||(pre?{item:pre.item,batch:pre.batch}:{});
  J.drawer({docs:["moves",old?.id],title:old?"Debit note":"Purchase return / debit note",submit:old?"Save":"Create debit note",body:`<div class="form">${fld("Date",dateI("date",old?.date||today()))}${fld("Return note no.",txt("inv",old?.inv))}</div>
    ${fld("Batch to return",`<select name="bk" id="f-bk"><option value="">Choose batch…</option>${opts.map(({it,b})=>`<option value="${it.id}|${esc(b.batch)}|${b.vendor}|${b.rate}" ${l0.batch===b.batch?"selected":""}>${esc(it.name)} · ${esc(b.batch)} · ${qf.format(b.qty)} ${esc(it.unit)} left @ ₹${inr.format(b.rate)} · ${esc(J.accName(b.vendor))}</option>`).join("")}${old?`<option value="${old.lines[0].item}|${esc(old.lines[0].batch)}|${old.vendor}|${old.lines[0].rate}" selected>${esc(itemName(old.lines[0].item))} · ${esc(old.lines[0].batch)} (current)</option>`:""}</select>`)}
    <div class="form">${fld("Qty returned",num("qty",l0.qty))}${fld("GST % on original bill",selO("gst",["0","5","12","18","28"],String(l0.gst??"5")))}</div>${fld("Reason",txt("note",old?.note,"Damaged, short-dated, quality…"))}
    <p class="hint">Creates a debit note: the vendor's balance goes down by the value plus GST, and Kitchen Purchases and Input GST are reversed.</p>`,
    onSubmit:async fd=>{if(!fd.bk)return "Choose a batch.";const [item,batch,vend,rate]=fd.bk.split("|");const qty=+fd.qty;if(!(qty>0))return "Enter the quantity returned.";const g=+fd.gst||0;const taxable=r2(qty*+rate),tax=r2(taxable*g/100);
      const id=old?.id||uid();const head=J.sysAcc("purch")?.id||await J.ensureAcc("Kitchen Purchases (Raw Material)","expense","purch");const reg=!!J.settings().gstin;const igst=tax&&reg?(J.sysAcc("igst")?.id||await J.ensureAcc("Input GST","tax","igst")):null;
      const v=await J.postVoucher({id:old?.vid,type:"debitnote",date:fd.date,lines:[{a:vend,dr:taxable+tax,cr:0},{a:head,dr:0,cr:reg?taxable:taxable+tax},...(igst?[{a:igst,dr:0,cr:tax}]:[])],party:vend,ref:fd.inv,narr:"Return · "+itemName(item)+" "+qty+" "+unitOf(item)+(fd.note?" · "+fd.note:""),gst:tax?{in:{[g]:[-taxable,-tax]}}:null,src:{col:"moves",id,label:"Inventory return"}});
      await J.store.put("moves",{id,type:"return",date:fd.date,m:fd.date.slice(0,7),vendor:vend,inv:fd.inv,note:fd.note,lines:[{item,qty,rate:+rate,gst:g,batch}],vid:v.id,createdAt:old?.createdAt||Date.now()});toast("Debit note "+v.no+" posted")}})}
J.act("newPurchase",()=>purchaseDrawer(null));J.act("buyItem",el=>purchaseDrawer(null,el.dataset.x));
J.act("deptPick",el=>{const r=document.getElementById("f-note");if(r&&el.value==="Counter Sell")r.value="Direct Sell";else if(r&&r.value==="Direct Sell")r.value="Kitchen usage"});J.act("newConsume",()=>consumeDrawer(null));J.act("useItem",el=>consumeDrawer(null,{item:el.dataset.x}));
J.act("useBatch",el=>{const [item]=el.dataset.x.split("|");const I=J.D.inv.items[item];const b=I.batches.find(x=>x.batch===el.dataset.x.split("|")[1]);consumeDrawer(null,{item,qty:b?r3(b.qty):""})});
J.act("newReturn",()=>returnDrawer(null));J.act("retBatch",el=>{const [item,batch]=el.dataset.x.split("|");returnDrawer(null,{item,batch})});
J.act("adjStock",()=>adjustDrawer(null));
const openMove=id=>{const m=J.get("moves",id);if(!m)return toast("Record not found");if(m.billId){J.go("inventory","bills");return toast("This purchase came from a supplier bill — see Inventory → Bills")}J.go("inventory",{purchase:"purchases",consume:"consumption",return:"returns",adjust:"adjust"}[m.type]);({purchase:purchaseDrawer,consume:consumeDrawer,return:returnDrawer,adjust:adjustDrawer})[m.type](m)};
J.openSrc.moves=openMove;J.act("editMove",el=>openMove(el.dataset.x));
J.act("delMove",async el=>{const m=J.get("moves",el.dataset.x);await J.safe(async()=>{if(m?.vid)await J.deleteVoucher(m.vid);await J.store.del("moves",m.id);if(m?.type==="purchase")await J.syncGroups(m.id,{...m,lines:[]})},"Deleted");S.confirm=null;J.render()});
J.act("postStock",async()=>{const val=ui().val==="avg"?J.D.inv.totalAvg:J.D.inv.total;await J.safe(async()=>{const st=J.sysAcc("stock")?.id||await J.ensureAcc("Closing Stock — Kitchen","stock","stock");const cogs=J.sysAcc("purch")?.id||await J.ensureAcc("Kitchen Purchases (Raw Material)","expense","purch");
  const cur=J.balanceOf(st),diff=r2(val-cur);if(Math.abs(diff)<0.01){toast("Stock in books already matches "+money(val));return}
  const v=await J.postVoucher({type:"journal",date:today(),lines:diff>0?[{a:st,dr:diff,cr:0},{a:cogs,dr:0,cr:diff}]:[{a:cogs,dr:-diff,cr:0},{a:st,dr:0,cr:-diff}],narr:"Month-end stock valuation ("+(ui().val==="avg"?"weighted average":"FIFO")+") "+money(val)});toast("Posted "+v.no+": stock "+(diff>0?"up ":"down ")+money(Math.abs(diff)))})});
J.act("exportStock",()=>{const inv=J.D.inv;const rows=[["Item","Category","Subcategory","Unit","Qty","Reorder","Last rate","FIFO value","Avg value","Nearest expiry"]];for(const it of J.all("items")){const I=inv.items[it.id];rows.push([it.name,it.cat,it.sub,it.unit,r3(I.qty),it.reorder||"",r2(I.last),r2(I.value),r2(I.valueAvg),I.nextExp])}J.saveFile("stock-"+today()+".csv",J.toCSV(rows))});
J.act("exportPurch",()=>{const U=ui(),[f,t]=periodRange(U.period,U);const rows=[["Date","Vendor","Invoice","Item","Batch","Qty","Unit","Rate","GST %","Taxable","GST","Expiry"]];for(const m of J.all("moves").filter(m=>m.type==="purchase"&&m.date>=f&&m.date<=t))for(const l of m.lines)rows.push([m.date,J.accName(m.vendor),m.inv,itemName(l.item),l.batch,l.qty,unitOf(l.item),l.rate,l.gst,r2(l.qty*l.rate),r2(l.qty*l.rate*l.gst/100),l.exp]);J.saveFile("purchase-register.csv",J.toCSV(rows))});

// ---------- Item master ----------
function vItems(){const U=ui();const items=J.all("items").filter(it=>!U.q||(it.name+" "+(it.sub||"")+" "+(it.cat||"")).toLowerCase().includes(U.q.toLowerCase())).sort((a,b)=>(a.cat||"").localeCompare(b.cat||"")||a.name.localeCompare(b.name));
  return `<div class="filters">${fld("Search",`<input id="it-q" data-ui="inv.q" value="${esc(U.q)}" placeholder="Name, category">`)}<div class="row" style="margin-left:auto"><button class="btn w" data-a="importItems">Import CSV</button><button class="btn primary w" data-a="newItem">New item</button></div></div>
  <div class="panel"><div class="tbl-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Subcategory</th><th>Unit</th><th class="num">Reorder</th><th>Default vendor</th><th>Classification</th><th></th></tr></thead><tbody>
  ${items.length?items.map(it=>`<tr><td><div class="row" style="gap:8px;flex-wrap:nowrap"><span class="avatar" style="width:30px;height:30px;cursor:pointer" data-go="inventory" data-tab="pics" title="Pictures">${it.img?`<img src="${esc(it.img)}" alt="">`:esc(J.initials(it.name))}</span>${esc(it.name)}${it.active===false?' <span class="chip plain">inactive</span>':""}</div></td><td>${esc(it.cat)}</td><td>${esc(it.sub||"")}</td><td>${esc(it.unit)}</td><td class="num">${it.reorder||"—"}</td><td>${esc(it.vendor?J.accName(it.vendor):"")}</td><td><span class="chip ok">Pure veg</span> ${NOT_JAIN.test(it.name)?'<span class="chip plain">Not Jain</span>':'<span class="chip plain">Jain-friendly</span>'}</td><td>${J.docsBtn("items",it,it.name)} <button class="btn small w" data-a="editItem" data-x="${it.id}">Edit</button></td></tr>`).join(""):J.emptyRow(8,"The item master is empty","Add ingredients one by one, or import a CSV with columns Name, Category, Subcategory, Unit, Reorder.")}
  </tbody></table></div></div>
  <div class="panel pb hint" id="impBox" hidden></div>`}
function itemDrawer(id){const it=id?J.get("items",id):{unit:"KG",cat:"Vegetables",gst:0,active:true};
  J.drawer({docs:["items",id],title:id?"Edit item":"New item",danger:id?J.delBtn("items",id,"Delete item"):"",submit:id?"Save item":"Add item",body:`<div class="row" style="gap:12px;align-items:center"><span class="avatar" id="imgPrev" style="width:56px;height:56px">${it.img?`<img src="${esc(it.img)}" alt="">`:esc(J.initials(it.name||"?"))}</span><label class="f">Photo<input type="file" id="f-img" accept="image/*" data-ach="pickImg"></label><input type="hidden" name="img" id="f-imgdata" value="${esc(it.img||"")}"></div>
    <div class="row" style="gap:8px;flex-wrap:wrap"><input name="imgUrl" id="f-imgUrl" placeholder="…or paste a picture link (e.g. from Hyperpure)" style="flex:1;min-width:240px" value="${/^https?:/.test(it.img||"")?esc(it.img):""}"><a class="btn small" href="https://www.hyperpure.com/in/search?q=${encodeURIComponent((it.name||"").replace(/\(.*?\)/g," ").trim())}" target="_blank" rel="noopener">Find on Hyperpure ↗</a></div>
    ${fld("Name",txt("name",it.name,"e.g. Paneer (fresh)","required"))}<div class="form">${fld("Category",selO("cat",CATS,it.cat))}${fld("Subcategory",txt("sub",it.sub,"e.g. Leafy, Cottage cheese"))}${fld("Unit",selO("unit",UNITS,it.unit))}${fld("Reorder level",num("reorder",it.reorder,"0"))}${fld("Default GST %",selO("gst",["0","5","12","18","28"],String(it.gst??0)))}${fld("Shelf life (days)",num("shelf",it.shelf,"for auto expiry"))}${fld("Brand",txt("brand",it.brand,"e.g. Amul"))}${fld("Flavour / variant",txt("variant",it.variant,"e.g. Mango"))}${fld("Pack size",txt("pack",it.pack,"e.g. 330 ml"))}${fld("Package type",selO("ptype",["","Pouch","Bottle","Can","Tetra pack","Carton","Box","Jar","Tub","Cup","Packet","Bag","Sachet","Loose","Other"],it.ptype||""))}${fld("MRP ₹ (per pack)",num("mrp",it.mrp,""))}</div>
    ${fld("Default vendor",J.selA("vendor",["vendor"],it.vendor,"None"))}${it.ref||it.url||it.specs||it.model?`<details><summary style="cursor:pointer">Product details${it.ref?" · "+esc(it.ref):""}</summary><table class="kv2" style="margin-top:6px"><tbody>${[["Model",it.model],["Manufacturer",it.mfr],["Product code",it.ref]].filter(x=>x[1]).map(([k,v])=>`<tr><th>${k}</th><td>${esc(v)}</td></tr>`).join("")}${it.specs&&typeof it.specs==="object"?Object.entries(it.specs).filter(([k])=>k!=="about").map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(String(v))}</td></tr>`).join(""):""}</tbody></table>${Array.isArray(it.specs?.about)?`<ul class="hint">${it.specs.about.map(b=>`<li>${esc(b)}</li>`).join("")}</ul>`:""}${it.url?`<a class="btn small" href="${esc(it.url)}" target="_blank" rel="noopener">Open product page ↗</a>`:""}</details>`:""}<label class="row" style="gap:8px"><input type="checkbox" name="active" id="f-active" ${it.active!==false?"checked":""}> Active</label>
    <p class="hint">Items are checked against non-vegetarian ingredients before saving. Names with onion, garlic or root vegetables are marked not Jain-friendly.</p>`,
    onSubmit:async fd=>{const name=fd.name.trim();if(!name)return "Enter the item name.";if(NONVEG.test(name)||NONVEG.test(fd.sub||""))return "“"+name+"” looks non-vegetarian. The item master only accepts pure-vegetarian ingredients.";
      if(J.all("items").some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))return "An item with this name already exists.";
      await J.store.put("items",{...(id?it:{}),id:id||uid(),name,cat:fd.cat,sub:fd.sub.trim(),unit:fd.unit,reorder:+fd.reorder||0,gst:+fd.gst||0,shelf:+fd.shelf||0,brand:(fd.brand||"").trim(),variant:(fd.variant||"").trim(),pack:(fd.pack||"").trim(),ptype:fd.ptype||"",mrp:+fd.mrp||0,vendor:fd.vendor,img:(fd.imgUrl||"").trim()||fd.img||"",veg:true,active:fd.active});toast(id?"Item saved":"Item added")}})}
J.act("pickImg",el=>{const f=el.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement("canvas"),s=96;c.width=c.height=s;const x=c.getContext("2d");const m=Math.min(img.width,img.height);x.drawImage(img,(img.width-m)/2,(img.height-m)/2,m,m,0,0,s,s);const d=c.toDataURL("image/jpeg",0.8);document.getElementById("f-imgdata").value=d;document.getElementById("imgPrev").innerHTML=`<img src="${d}" alt="">`};img.src=r.result};r.readAsDataURL(f)});
// ---------- Pictures: pick straight from the Hyperpure search page, no item form ----------
const hpQ=n=>String(n||"").replace(/\(.*?\)/g," ").replace(/\b(economy|premium|desi|fresh|peeled)\b/ig," ").replace(/\s+/g," ").trim();
const hpUrl=n=>"https://www.hyperpure.com/ind/kolkata/search?q="+encodeURIComponent(hpQ(n));
function vPics(){const U=J.ui("invpic",{all:false,q:""});const buy={};for(const m of J.all("moves").filter(m=>m.type==="purchase"))for(const l of m.lines||[]){const b=buy[l.item]??={n:0,last:"",hp:false};b.n++;if(m.date>b.last)b.last=m.date;if(/hyperpure/i.test(J.accName(m.vendor)))b.hp=true}
  const list=J.all("items").filter(it=>it.active!==false&&(U.all||buy[it.id])&&(!U.q||it.name.toLowerCase().includes(U.q.toLowerCase()))).sort((a,b)=>(!!a.img-!!b.img)||(buy[b.id]?.hp-buy[a.id]?.hp)||a.name.localeCompare(b.name));
  const miss=list.filter(it=>!it.img).length;
  return `<div class="filters">${fld("Search",`<input data-ui="invpic.q" value="${esc(U.q)}" placeholder="Item name">`)}<label class="row" style="gap:6px"><input type="checkbox" data-set="invpic.all=${U.all?"":"1"}" ${U.all?"checked":""}> Show all items, not only purchased ones</label><span class="hint">${miss} without a picture</span></div>
  <div class="note"><b>How:</b> tap <b>Find on Hyperpure</b> — the search opens beside this screen. Then either <b>drag the product picture</b> onto the item's box here, or right-click it → <b>Copy image</b> and click the box and press <b>Ctrl+V</b>. A copied picture link or a photo from your phone works too. It saves at once.</div>
  <div class="pic-grid">${list.map(it=>{const b=buy[it.id];return J.picCard({id:it.id,col:"items",size:160,name:it.name,img:it.img,meta:b?`${b.n} purchase${b.n>1?"s":""} · last ${fmtDate(b.last)}${b.hp?" · Hyperpure":""}`:"not purchased yet",search:hpUrl(it.name),searchLabel:"Find on Hyperpure"})}).join("")||`<p class="muted pb">No items.</p>`}</div>`}
J.act("newItem",()=>itemDrawer(null));J.act("editItem",el=>itemDrawer(el.dataset.x));
J.act("importItems",()=>J.openImport("stock"));

// ---------- Best price ----------
function vBest(){const U=ui();const inv=J.D.inv;const since=addDays(today(),-90);const items=J.all("items").filter(it=>!U.bpCat||it.cat===U.bpCat);
  const rows=items.map(it=>{const buys=(inv.items[it.id]?.buys||[]).filter(b=>b.date>=since);if(!buys.length)return null;const byV={};for(const b of buys){const v=byV[b.vendor]??={vendor:b.vendor,min:Infinity,last:0,lastDate:"",n:0,qty:0,amt:0};v.min=Math.min(v.min,b.rate);if(b.date>=v.lastDate){v.last=b.rate;v.lastDate=b.date}v.n++;v.qty+=b.qty;v.amt+=b.qty*b.rate}
    const vs=Object.values(byV).map(v=>({...v,avg:v.amt/v.qty})).sort((a,b)=>a.avg-b.avg);const latest=buys.at(-1);const best=vs[0];const save=Math.max(0,latest.rate-best.avg);return {it,vs,latest,best,save,monthly:(inv.items[it.id]?.used30||0)*save}}).filter(Boolean).sort((a,b)=>b.monthly-a.monthly);
  const groups={};for(const r of rows)(groups[(r.it.cat||"Other")+(r.it.sub?" · "+r.it.sub:"")]??=[]).push(r);
  return `<div class="filters">${fld("Category",`<select id="bp-cat" data-ui="inv.bpCat"><option value="">All</option>${CATS.map(c=>`<option ${U.bpCat===c?"selected":""}>${c}</option>`).join("")}</select>`)}<span class="hint">Last 90 days of purchases, compared vendor by vendor within each subcategory.</span></div>
  ${rows.length?`<div class="panel"><div class="tbl-wrap"><table><thead><tr><th>Item</th><th>Vendors (avg rate · purchases)</th><th class="num">Latest rate paid</th><th class="num">Best avg</th><th>Recommendation</th><th class="num">Monthly saving</th></tr></thead><tbody>
  ${Object.entries(groups).map(([g,rs])=>`<tr><td colspan="6" style="font-weight:700;color:var(--bahi);font-size:11.5px;letter-spacing:.06em;text-transform:uppercase">${esc(g)}</td></tr>`+rs.map(r=>`<tr><td>${esc(r.it.name)}<div class="muted" style="font-size:12px">per ${esc(r.it.unit)}</div></td><td>${r.vs.map((v,i)=>`<div>${i===0?'<span class="chip ok">Best</span> ':""}${esc(J.accName(v.vendor))} · ₹${inr.format(v.avg)} · ${v.n}×</div>`).join("")}</td><td class="num">₹${inr.format(r.latest.rate)}<div class="muted" style="font-size:12px">${esc(J.accName(r.latest.vendor))}</div></td><td class="num">₹${inr.format(r.best.avg)}</td><td>${r.save>0.009&&r.best.vendor!==r.latest.vendor?`Buy from <b>${esc(J.accName(r.best.vendor))}</b>: ₹${inr.format(r.save)} less per ${esc(r.it.unit)}`:'<span class="muted">Already at best rate</span>'}</td><td class="num">${r.monthly>0.5?money0(r.monthly):"—"}</td></tr>`).join("")).join("")}
  </tbody></table></div></div><p class="hint">Monthly saving = rate gap × quantity used in the last 30 days.</p>`:`<div class="panel"><div class="empty"><strong>No purchase history yet</strong><span>Rates are compared once the same item has been bought, ideally from more than one vendor.</span></div></div>`}`}

// ---------- Recipes ----------
function recipeCost(rc){let cost=0;const rows=(rc.lines||[]).map(l=>{const it=J.get("items",l.item);const c=it?J.itemCost(l.item,l.qty,l.unit):0;cost+=c;return {...l,it,c}});const per=rc.yield>0?cost/rc.yield:cost;return {rows,cost,per}}
J.recipeCost=recipeCost;
function vRecipes(){const tgt=+J.settings().targetFood||32;const rs=J.all("recipes").sort((a,b)=>a.name.localeCompare(b.name));
  return `<div class="filters"><span class="hint">Cost per portion uses each ingredient's latest purchase rate. Target food cost: ${tgt}% (change in Settings).</span><button class="btn primary w" data-a="newRecipe" style="margin-left:auto">New recipe</button></div>
  <div class="panel"><div class="tbl-wrap"><table><thead><tr><th>Dish</th><th class="num">Yield</th><th class="num">Batch cost</th><th class="num">Cost / portion</th><th class="num">Selling price</th><th class="num">Food cost %</th><th class="num">Price at ${tgt}%</th><th></th></tr></thead><tbody>
  ${rs.length?rs.map(rc=>{const c=recipeCost(rc);const fc=rc.price?c.per/rc.price*100:0;const rec=c.per/(tgt/100);return `<tr><td>${esc(rc.name)}<div class="muted" style="font-size:12px">${(rc.lines||[]).length} ingredients</div></td><td class="num">${rc.yield||1}</td><td class="num">${inr.format(c.cost)}</td><td class="num"><b>${inr.format(c.per)}</b></td><td class="num">${rc.price?inr.format(rc.price):"—"}</td><td class="num">${rc.price?`<span class="chip ${fc<=tgt?"ok":fc<=tgt+8?"warn":"bad"}">${fc.toFixed(1)}%</span>`:"—"}</td><td class="num">₹${J.inr0.format(Math.ceil(rec/5)*5)}</td><td><button class="btn small w" data-a="editRecipe" data-x="${rc.id}">Edit</button></td></tr>`}).join(""):J.emptyRow(8,"No recipes yet","Add a dish with its ingredients to see cost per plate and the price that hits your target food cost.")}
  </tbody></table></div></div>`}
function recipeDrawer(id){const rc=id?J.get("recipes",id):{yield:1,lines:[]};const n=Math.max(8,(rc.lines?.length||0)+2);
  const row=(i,l={})=>{const it=l.item?J.get("items",l.item):null;const units=it?(CONV[it.unit]?Object.keys(CONV[it.unit]):[it.unit]):UNITS;return `<tr><td style="min-width:200px"><select name="ln-item-${i}" id="f-ln-item-${i}">${itemOpts(l.item)}</select></td><td style="min-width:90px"><input name="ln-qty-${i}" id="f-ln-qty-${i}" type="number" step="any" value="${esc(l.qty??"")}"></td><td style="min-width:80px"><select name="ln-unit-${i}" id="f-ln-unit-${i}"><option value="">item unit</option>${UNITS.map(u=>`<option ${l.unit===u?"selected":""}>${u}</option>`).join("")}</select></td></tr>`};
  J.drawer({title:id?"Edit recipe":"New recipe",wide:true,submit:"Save recipe",danger:id?J.delBtn("recipes",id,"Delete recipe"):"",body:`<div class="form">${fld("Dish name",txt("name",rc.name,"e.g. Paneer Butter Masala","required"))}${fld("Portions this recipe makes",num("yield",rc.yield,"1"))}${fld("Menu selling price (₹)",num("price",rc.price))}</div>
    <div class="tbl-wrap"><table class="lines-tbl"><thead><tr><th>Ingredient</th><th>Qty</th><th>Unit</th></tr></thead><tbody id="lnBody">${[...Array(n)].map((_,i)=>row(i,rc.lines?.[i])).join("")}</tbody></table></div>
    <p class="hint">Enter quantities for the whole batch. Grams and millilitres convert automatically for items stocked in KG or litres. Linking this recipe to a menu item lets KOT sales deduct stock at month-end.</p>`,
    onSubmit:async fd=>{const name=fd.name.trim();if(!name)return "Enter the dish name.";const lines=[];for(let i=0;i<60;i++){if(!(("ln-item-"+i) in fd))break;if(fd["ln-item-"+i]&&+fd["ln-qty-"+i])lines.push({item:fd["ln-item-"+i],qty:+fd["ln-qty-"+i],unit:fd["ln-unit-"+i]||""})}
      await J.store.put("recipes",{...(id?rc:{}),id:id||uid(),name,yield:+fd.yield||1,price:+fd.price||0,lines});toast("Recipe saved")}})}
J.act("newRecipe",()=>recipeDrawer(null));J.act("editRecipe",el=>recipeDrawer(el.dataset.x));

J.mod({id:"inventory",label:"Inventory",group:"Operations",icon:'<path d="M3 7l9-4 9 4-9 4-9-4z"/><path d="M3 7v10l9 4 9-4V7"/><path d="M12 11v10"/>',sub:"Pure-vegetarian stores: batches, expiry, purchases and costing.",
  headBtns:()=>`<button class="btn w" data-a="billUpload">Upload bills</button><button class="btn w" data-a="platBill">Upload Flipkart / Amazon / Zepto… bill</button><button class="btn w" data-a="impOpen" data-x="purch">Import</button><button class="btn w" data-a="newConsume">Log consumption</button><button class="btn primary w" data-a="newPurchase">New purchase</button>`,
  badge:()=>{const inv=J.D.inv;if(!inv)return 0;return J.all("items").flatMap(it=>inv.items[it.id]?.batches||[]).filter(b=>["bad","crit"].includes(expState(b.exp)?.[0])).length},
  tabs:[["stock","Stock in hand",vStock],["expiry","Expiry audit",vExpiry],["purchases","Purchases",vPurch],["consumption","Consumption",vCons],["returns","Returns",vRet],["adjust","Adjustments",vAdj],["bills","Bills",()=>J.vBills?.()||""],["items","Item master",vItems],["pics","Pictures",vPics],["best","Best price",vBest],["recipes","Recipe costing",vRecipes]]});
})();
/* structured purchase creation, used by the import centre */
(()=>{const J=window.J,{r2,uid}=J;
J.createPurchase=async(p,{post=true}={})=>{const id=p.id||uid(),stamp=p.date.replace(/-/g,"");const lines=p.lines.map((l,i)=>({item:l.item,qty:+l.qty,rate:+l.rate,gst:+l.gst||0,exp:l.exp||"",mrp:+l.mrp||0,mfg:l.mfg||"",expRaw:l.expRaw||"",...(l.personal||l.grp==="personal"?{personal:true}:{}),...(l.grp?{grp:l.grp}:{}),...Object.fromEntries(["ref","url","seller","model","wty","wtyu","acat","ecat","pcat"].filter(k=>l[k]).map(k=>[k,l[k]])),batch:l.batch||"BATCH-"+stamp+"-"+id.slice(-4).toUpperCase()+(i+1)}));let vid=null;
  if(post){const taxable=r2(lines.reduce((s,l)=>s+l.qty*l.rate,0)),gr={};let tax=0;for(const l of lines){const t=r2(l.qty*l.rate*l.gst/100);tax+=t;if(l.gst){gr[l.gst]=gr[l.gst]||[0,0];gr[l.gst][0]=r2(gr[l.gst][0]+l.qty*l.rate);gr[l.gst][1]=r2(gr[l.gst][1]+t)}}tax=r2(tax);const total=r2(taxable+tax);
    const head=J.sysAcc("purch")?.id||await J.ensureAcc("Kitchen Purchases (Raw Material)","expense","purch");const igst=tax?(J.sysAcc("igst")?.id||await J.ensureAcc("Input GST","tax","igst")):null;
    const L=[{a:head,dr:taxable,cr:0},...(tax?[{a:igst,dr:tax,cr:0}]:[]),{a:p.vendor,dr:0,cr:total}];if(p.paid)L.push({a:p.vendor,dr:total,cr:0},{a:p.paid,dr:0,cr:total});
    vid=(await J.postVoucher({type:"purchase",date:p.date,lines:L,party:p.vendor,ref:p.inv,narr:"Stock purchase · "+lines.map(l=>J.get("items",l.item)?.name).slice(0,4).join(", ")+(lines.length>4?"…":""),gst:Object.keys(gr).length?{in:gr}:null,src:{col:"moves",id,label:"Inventory"},f:{due:p.due||""}})).id}
  await J.store.put("moves",{id,type:"purchase",date:p.date,m:p.date.slice(0,7),vendor:p.vendor,inv:p.inv||"",due:p.due||"",paid:p.paid||"",lines,note:p.note||"",vid,imp:p.imp||"",createdAt:Date.now()});if(lines.some(l=>l.grp||l.personal))await J.syncGroups(id,{id,date:p.date,vendor:p.vendor,inv:p.inv||"",lines});return {id,vid}};
/* Groups on a purchase bill. Each line is Inventory (default), Personal, Expense or Asset, and can be moved between
   groups at any time. Non-inventory lines get an automatic consumption record (drawn from that bill's own batches, so
   they never sit in kitchen stock) and a journal moving their cost (incl. GST) out of Kitchen Purchases: Personal →
   Owner's personal purchases (hold), Expense → Consumables & small items, Asset → a fixed-asset record of its own
   (with warranty) and its asset ledger. Re-saving rebuilds everything, so changing a line's group moves it cleanly. */
const GSET={personal:{dept:"Personal",acc:["Owner's personal purchases (hold)","capital","persbuy"],pre:"pers-"},expense:{dept:"Expense (non-stock)",acc:["Consumables & small items (from purchases)","expense","consumables"],pre:"exps-"},asset:{dept:"Fixed asset",pre:"asts-"}};
const grpOf=l=>l.grp||(l.personal?"personal":"");
J.syncGroups=async(id,mv)=>{const m=mv||J.get("moves",id);const lines=m?.lines||[];const head=()=>J.sysAcc("purch")?.id||J.ensureAcc("Kitchen Purchases (Raw Material)","expense","purch");const val=l=>r2(l.qty*l.rate*(1+(+l.gst||0)/100));
  for(const [g,G] of Object.entries(GSET)){const pl=lines.filter(l=>grpOf(l)===g);const mid=G.pre+id;
    if(!pl.length){if(J.get("moves",mid))await J.store.del("moves",mid);if(g!=="asset")await J.deleteVoucher?.(mid);continue}
    await J.store.put("moves",{id:mid,type:"consume",auto:g,src:id,date:m.date,m:m.date.slice(0,7),dept:G.dept,note:G.dept+" — moved out of stock on purchase "+(m.inv||""),lines:pl.map(l=>({item:l.item,qty:l.qty,batch:l.batch})),createdAt:(m.createdAt||Date.now())+1});
    if(g!=="asset"){const amt=r2(pl.reduce((s,l)=>s+val(l),0));const dflt=J.sysAcc(G.acc[2])?.id||await J.ensureAcc(...G.acc);const byA={};
      for(const l of pl){const a=g==="expense"&&l.ecat?await J.ensureAcc("Expenses — "+l.ecat,"expense"):dflt;byA[a]=r2((byA[a]||0)+val(l))}
      await J.postVoucher({id:mid,type:"journal",date:m.date,lines:[...Object.entries(byA).map(([a,v])=>({a,dr:v,cr:0})),{a:await head(),dr:0,cr:amt}],party:m.vendor,ref:m.inv,narr:G.dept+" items on purchase "+(m.inv||"")+" · "+pl.map(l=>J.get("items",l.item)?.name).slice(0,4).join(", ")+(pl.length>4?"…":""),src:{col:"moves",id,label:"Inventory"}})}}
  // assets: one register entry per asset line (keyed by batch so it survives re-saves); entries for lines no longer marked Asset are removed
  const keep=new Set();for(const l of lines.filter(l=>grpOf(l)==="asset")){const aid="pa-"+String(l.batch||"").replace(/[^A-Za-z0-9-]/g,"");keep.add(aid);const it=J.get("items",l.item)||{};const old=J.get("assets",aid)||{};const cost=val(l);
    const acc=old.acc||await J.ensureAcc("Asset — "+(it.name||"item")+(J.all("accounts").some(x=>x.name==="Asset — "+it.name&&x.id!==old.acc)?" ("+aid.slice(-5)+")":""),"asset");
    const cat=(old.catSet?old.cat:l.acat)||old.cat||"Kitchen equipment";const LIFE={"Kitchen equipment":15,"Furniture & fixtures":10,"POS terminals & computers":3,"Electrical installations":10,"Office equipment":5};
    await J.store.put("assets",{maint:[],method:"SLM",life:LIFE[cat]||10,rate:15,...old,id:aid,name:old.nameSet?old.name:(it.name||"Item")+(l.qty>1?" × "+l.qty:""),cat,date:old.dateSet?old.date:m.date,cost,salvage:old.salvage??r2(cost*0.05),vendor:m.vendor,serial:old.serial||l.model||"",acc,src:{move:id,batch:l.batch},img:old.img||it.img||"",warranty:{till:l.wtyu||old.warranty?.till||"",text:l.wty||old.warranty?.text||""},ref:l.ref||it.ref||"",url:l.url||it.url||""});
    await J.postVoucher({id:aid,type:"journal",date:m.date,lines:[{a:acc,dr:cost,cr:0},{a:await head(),dr:0,cr:cost}],party:m.vendor,ref:m.inv,narr:"Asset from purchase "+(m.inv||"")+" · "+(it.name||""),src:{col:"assets",id:aid,label:"Fixed assets"}})}
  for(const a of J.all("assets").filter(a=>a.src?.move===id&&!keep.has(a.id))){await J.deleteVoucher?.(a.id);await J.store.del("assets",a.id)}};
J.syncPersonal=J.syncGroups;
})();
